   ["STRINGS.SKILLTREE.WURT.WURT_SHADOW_ALLEGIANCE_1_DESC"] = "ผู้ติดตามเมิร์มของคุณอาจจะตาย แต่เงาของพวกเขายังมีชีวิตอยู่\nเติมพลัง Planar ให้กับเงาของเมิร์มที่ล้มลงโดยใช้ สยองขวัญบริสุทธิ์(Pure Horror)",
   ["STRINGS.SKILLTREE.WENDY.WENDY_POTION_YIELD_DESC"] = "บางครั้ง เวนดี้(Wendy)สามารถคั้นน้ำยาพิเศษออกมาจากส่วนผสมเดียวกันได้",
   ["STRINGS.SKILLTREE.WALTER.WALTER_AMMO_UTILITY_DESC"] = "เรียนรู้วิธีสร้าง กระสุนเหนียว(Stickies) และ กระสุนเศษเหล็ก(Shockscrap Shots) กระสุนเหนียว(Stickies) จะทำให้เป้าหมายที่โดนโจมตีช้าลง และ กระสุนเศษเหล็ก(Shockscrap Shots) จะสร้างความเสียหายไฟฟ้าพร้อมอัตราการทำให้มึนงงที่สูงกว่า",
   ["STRINGS.SKILLTREE.WURT.WURT_MOSQUITO_CRAFT_3_DESC"] = "เชี่ยวชาญการใช้สิ่งของที่มีส่วนประกอบของยุง(Mosquito)\n\nด้วยความช่วยเหลือของ ลิลจอมคัน(Lil' Itchy) จับยุง(Mosquito)จากอากาศได้เลย",
   ["STRINGS.SKILLTREE.WORTOX.WORTOX_LIFTEDSPIRITS_3_DESC"] = "วิญญาณ(Soul) Echo จะเกิดขึ้นอีกครั้ง\nสิ่งนี้จะไม่ลดค่าใช้จ่าย วิญญาณ(Soul) Hop จากแผนที่",
   ["STRINGS.SKILLTREE.WORTOX.WORTOX_LIFTEDSPIRITS_4_DESC"] = "ค่าใช้จ่ายของ วิญญาณ(Soul) Hop จากแผนที่จะลดลงตามพื้นที่ของโลกปัจจุบันที่ได้รับการสำรวจ",
   ["STRINGS.SKILLTREE.WORTOX.WORTOX_SOULJAR_1_DESC"] = "เรียนรู้วิธีการประดิษฐ์และใช้ วิญญาณ(Soul) Jar เพื่อเก็บวิญญาณ(Soul)ไว้ใช้ในภายหลัง วิญญาณ(Soul) Jar จะรั่วไหลวิญญาณ(Soul)ออกมาเมื่อถึงเวลาที่ไม่ได้อยู่ในคลังสินค้าของคุณ",
   ["STRINGS.SKILLTREE.WINONA.WINONA_CHARLIE_2_LOCK_DESC"] = "จำเป็นต้องใช้ทักษะ เงา(Shadow) Seeker I และไม่มี Founder's Keepers II เพื่อปลดล็อค",
   ["STRINGS.SKILLTREE.WORTOX.WORTOX_ALLEGIANCE_LUNAR_DESC"] = "Cryptic Founder จะให้รางวัลแก่ความอยากรู้อยากเห็นของคุณด้วยการแสดงพลังจากการสวมหมวกร่มไม้สดใส(Brightshade Helm) หรือชุดเกราะร่มไม้สดใส(Brightshade Armor) วิญญาณ(Soul)ที่รอการปลดปล่อยใน วิญญาณ(Soul) Echo จะดูดซับความเสียหายที่เข้ามาและหมดเวลาลง",
   ["STRINGS.SKILLTREE.WILLOW.WILLOW_BERNIEREGEN_1_DESC"] = "สุขภาพของ เบอร์นี่(Bernie) ฟื้นฟูอย่างช้าๆ",
   ["STRINGS.SKILLTREE.WORTOX.WORTOX_INCLINATION_METER_TITLE"] = "ตาชั่ง",
   ["STRINGS.SKILLTREE.WINONA.WINONA_SHADOW_2_TITLE"] = "เครื่องกำเนิดความสยองขวัญล้วนๆ",
   ["STRINGS.SKILLTREE.WORTOX.WORTOX_ALLEGIANCE_SHADOW_DESC"] = "ราชินีจะตอบแทนความภักดีของคุณด้วยการปลดล็อกพลังจากการใช้ เคียวยมทูต(เงา(Shadow) Reaper) วิญญาณ(Soul)ที่รอการปลดปล่อยใน วิญญาณ(Soul) Echo จะสร้างความเสียหายที่กระจายออกไปเพื่อเข้าใกล้ศัตรูหรือโจมตีเป้าหมายหนึ่งเป้าหมายสองครั้ง และหมดเวลาลง",
   ["STRINGS.SKILLTREE.WINONA.WINONA_SHADOW_3_LOCK_DESC"] = "ต้องใช้ทักษะ Portability และ สยองขวัญบริสุทธิ์(Pure Horror) Generator จึงจะปลดล็อคได้",
   ["STRINGS.SKILLTREE.WINONA.WINONA_CHARLIE_2_TITLE"] = "ผู้แสวงหาเงา(Shadow) II",
   ["STRINGS.SKILLTREE.WURT.WURT_CIV_2_DESC"] = "เรียนรู้วิธีประดิษฐ์ โรงเก็บของเครื่องมือต๊อกต๋อย(Shoddy Tool)(เครื่องมือต๊อกต๋อย(Shoddy Tool) Shed) เพื่อเตรียมเครื่องมือ Shoddy ให้กับคนงานเมิร์มของคุณ",
   ["STRINGS.SKILLTREE.WORTOX.WORTOX_SOULDECOY_1_TITLE"] = "วิญญาณ(Soul)ล่อลวงฉัน",
   ["STRINGS.SKILLTREE.WINONA.WINONA_SHADOW_2_DESC"] = "เรียนรู้วิธีใช้ สยองขวัญบริสุทธิ์(Pure Horror) เป็นแหล่งเชื้อเพลิงสำหรับเครื่องปั่นไฟ",
   ["STRINGS.SKILLTREE.WALTER.WALTER_AMMO_BAG_DESC"] = "เรียนรู้วิธีประดิษฐ์กระเป๋าใส่กระสุนเพื่อใส่กระสุนส่วนเกินของคุณ",
   ["STRINGS.SKILLTREE.WOODIE.WOODIE_HUMAN_TREEGUARD_1_TITLE"] = "ทรีการ์ด เฟลเลอร์ I",
   ["STRINGS.SKILLTREE.WILLOW.WILLOW_ALLEGIANCE_LOCK_2_DESC"] = "เรียนรู้ 6 ทักษะของเบอร์นี่(Bernie)เพื่อปลดล็อค",
   ["STRINGS.SKILLTREE.WATHGRITHR.WATHGRITHR_SONGS_REVIVEWARRIOR_DESC"] = "เรียนรู้การสร้าง การกลับมาอีกครั้งของนักรบ(Warrior's Reprise): นำพันธมิตรของคุณกลับมามีชีวิตอีกครั้งเพื่อการแสดงอังกอร์",
   ["STRINGS.SKILLTREE.WILLOW.WILLOW_ALLEGIANCE_LOCK_4_DESC"] = "ค้นหาและเอาชนะ แชมป์สวรรค์(Celestial Champion)\nไม่มีทักษะ เงา(Shadow) Allegiance",
   ["STRINGS.SKILLTREE.WORMWOOD.ARMOR_BRAMBLE_TITLE"] = "ผู้เชี่ยวชาญเกราะหนาม(Bramble Husk)",
   ["STRINGS.SKILLTREE.ALLEGIANCE_LOCK_2_DESC"] = "ค้นหาและกำจัดโครงกระดูกโบราณ(Ancient Fuelweaver)",
   ["STRINGS.SKILLTREE.WORTOX.WORTOX_INCLINATION_NAUGHTY_DESC"] = "ความโลภของคุณทำให้คุณหยุดรับพลังวิญญาณ(Soul)มากเกินไปชั่วขณะหนึ่ง\nการกินหรือปล่อยวิญญาณ(Soul)จะไม่เปลี่ยนความมีสติอีกต่อไป วิญญาณ(Soul)จะรักษาคุณด้วยค่าใช้จ่ายที่น้อยลง",
   ["STRINGS.SKILLTREE.WILLOW.WILLOW_ALLEGIANCE_LOCK_6_DESC"] = "เรียนรู้ 6 ทักษะของเบอร์นี่(Bernie)เพื่อปลดล็อค",
   ["STRINGS.SKILLTREE.WATHGRITHR.WATHGRITHR_SONGS_CONTAINER_DESC"] = "เรียนรู้การสร้าง กระป๋องโทรรบ(Battle Call Canister) ซึ่งเป็นโซลูชันการจัดเก็บข้อมูลสำหรับ Battle Songs และ Battle Stingers",
   ["STRINGS.SKILLTREE.WILLOW.WILLOW_BERNIESANITY_1_DESC"] = "เบอร์นี่(Bernie)จะกลายเป็นแอนิเมชั่นที่ขีดจำกัดสติที่สูงกว่า",
   ["STRINGS.SKILLTREE.WILLOW.WILLOW_FIRE_BALL_TITLE"] = "ลูกบอลไฟ",
   ["STRINGS.SKILLTREE.WILLOW.WILLOW_CONTROLLED_BURN_1_DESC"] = "ไฟที่ควบคุมไว้จะไม่ลาม และของที่ติดไฟได้จะมอดลงไปเฉยๆ\nไอเทมอย่างคบเพลิงและไฟแช็กของวิลโลว์(Willow)มีโอกาส 100% ที่จะจุดไฟเผาเป้าหมาย",
   ["STRINGS.SKILLTREE.WILLOW.WILLOW_BERNIEAI_DESC"] = "เบอร์นี่(Bernie)จะเปิดใช้งานเพื่อต่อสู้กับสิ่งมีชีวิตที่อยู่ในแนวดวงจันทร์และเงาที่ไม่เป็นมิตร โดยไม่คำนึงถึงสุขภาพจิตของวิลโลว์(Willow)",
   ["STRINGS.SKILLTREE.WORMWOOD.BERRYBUSHCRAFTING_TITLE"] = "การประดิษฐ์ของต้นเบอร์รี่(Berry Bush)",
   ["STRINGS.SKILLTREE.WATHGRITHR.WATHGRITHR_ARSENAL_SPEAR_5_TITLE"] = "การเพิ่มประสิทธิภาพหอก(Spear)เอลดิง II",
   ["STRINGS.SKILLTREE.WILSON.WILSON_TORCH_6_TITLE"] = "ระยะคบเพลิง(Torch) III",
   ["STRINGS.SKILLTREE.WILSON.WILSON_TORCH_1_LOCK_DESC"] = "เรียนรู้ 3 ทักษะไฟฉายเพื่อปลดล็อก",
   ["STRINGS.SKILLTREE.WALTER.WALTER_CAMP_FIRSTAID_DESC"] = "เรียนรู้วิธีการใช้ไอเทมรักษาให้เร็วขึ้นและได้รับโบนัสเอฟเฟกต์ 50% รวมถึงเรียนรู้วิธีการประดิษฐ์ ปีกลายแถบ(Flutter Strip)",
   ["STRINGS.SKILLTREE.WORMWOOD.MUSHROOMPLANTER_UPGRADE_DESC"] = "เห็ด(Mushroom)ที่ปลูกในเครื่องเพาะเห็ด(Mushroom)ให้ผลผลิตสูงกว่า",
   ["STRINGS.SKILLTREE.WILLOW.WILLOW_BERNIESPEED_2_DESC"] = "ความเร็วในการเคลื่อนที่ของเบอร์นี่(Bernie)เร็วขึ้นมาก",
   ["STRINGS.SKILLTREE.WATHGRITHR.WATHGRITHR_SONGS_CONTAINER_TITLE"] = "กล่องเรียกการต่อสู้",
   ["STRINGS.SKILLTREE.WORMWOOD.MUSHROOMPLANTER_RATEBONUS_1_DESC"] = "เห็ด(Mushroom)ที่ปลูกในเครื่องเพาะเห็ด(Mushroom)จะเติบโตเร็วขึ้นเล็กน้อย",
   ["STRINGS.SKILLTREE.WILSON.WILSON_ALCHEMY_7_DESC"] = "แปรรูป ดินประสิว(Nitre) 3 อัน เป็นทอง(Gold Nugget)\nแปรรูป ทอง(Gold Nugget) 2 อัน เป็นดินประสิว(Nitre)",
   ["STRINGS.SKILLTREE.WINONA.WINONA_WAGSTAFF_2_DESC"] = "ขยายขอบเขตของ หมวกแว่นตา(Inspectacles) ของคุณเพื่อค้นหาแคชซัพพลายเกรดสูงกว่า\nรับความเชี่ยวชาญเหนือเทคโนโลยีทั้งหมดที่พบใน Advanced Cacheboxes",
   ["STRINGS.SKILLTREE.WILSON.WILSON_ALCHEMY_8_DESC"] = "แปรรูป หินตัด(Cut Stone) 2 ชิ้น เป็นหินอ่อน(Marble)\nแปรรูป หินอ่อน(Marble) เป็นหินตัด(Cut Stone)\nแปรรูป หินอ่อน(Marble) 2 อัน เป็นก้อนหินจันทรา(Moon Rock)",
   ["STRINGS.SKILLTREE.WILSON.WILSON_ALCHEMY_4_DESC"] = "แปรรูป เศษเนื้อ(Meat) 3 ชิ้น เป็นเนื้อ(Meat)\nแปรรูป เนื้อ(Meat) เป็นเศษชิ้น 2 ชิ้น",
   ["STRINGS.SKILLTREE.WILSON.WILSON_ALCHEMY_2_DESC"] = "แปรรูป อัญมณีแดง(Red Gem) 2 เม็ด เป็นอัญมณีน้ำเงิน(Blue Gem)\nแปรรูป อัญมณีน้ำเงิน(Blue Gem) 2 เม็ด เป็นอัญมณีแดง(Red Gem)\nแปรรูป อัญมณีน้ำเงิน(Blue Gem)และแดง เป็นอัญมณีม่วง(Purple Gem)",
   ["STRINGS.SKILLTREE.WOODIE.WOODIE_HUMAN_LUCY_3_DESC"] = "ใช้ลูซี่แกะสลักไม้เท้าเพื่อให้เคลื่อนย้ายได้สะดวก",
   ["STRINGS.SKILLTREE.WILSON.WILSON_ALCHEMY_6_DESC"] = "แปรรูป อัญมณีเหลือง 3 เม็ด เป็นอัญมณีเขียว(Green Gem)\nแปรรูป อัญมณี 6 เม็ดที่สีต่างกัน เป็นอัญมณีรุ้ง(Iridescent Gem)",
   ["STRINGS.SKILLTREE.WILSON.WILSON_BEARD_7_TITLE"] = "ที่เก็บหนวดเครา(Beard Hair)",
   ["STRINGS.SKILLTREE.WENDY.WENDY_SHADOW_3_TITLE"] = "พี่น้องแห่งเงา(Shadow) III",
   ["STRINGS.SKILLTREE.WORMWOOD.MOON_CAP_EATING_DESC"] = "เรียนรู้วิธีปลูกชรูมจันทราในเครื่องปลูกเห็ด(Mushroom) และปล่อยสปอร์ที่ทำให้ง่วงนอนเมื่อรับประทานพวกมัน",
   ["STRINGS.SKILLTREE.WALTER.WALTER_WOBY_SPRINT_DESC"] = "หลังจากที่ โวบี้(Woby) วิ่งไปได้ 3 วินาทีในขณะที่อยู่บนหลังม้า เธอจะเริ่มวิ่งด้วยความเร็วคงที่ที่สูงขึ้นจนกว่าจะถูกขัดจังหวะ",
   ["STRINGS.SKILLTREE.WILSON.WILSON_ALCHEMY_1_DESC"] = "แปรรูป กิ่งไม้(Twigs) 3 อันให้ เป็นท่อนไม้(Log)\nแปรรูป ท่อนไม้(Log) เป็นกิ่งไม้(Twigs) 2 อัน",
   ["STRINGS.SKILLTREE.WOODIE.WOODIE_HUMAN_TREEGUARD_2_TITLE"] = "ทรีการ์ด เฟลเลอร์ II",
   ["STRINGS.SKILLTREE.WINONA.WINONA_CATAPULT_BOOST_DESC"] = "เครื่องยิงทุกเครื่องที่อยู่ในระยะของ รีโมทที่มีประโยชน์(Handy Remote) ของคุณจะมีอัตราการยิงที่เพิ่มขึ้นในช่วงระยะเวลาสั้นๆ",
   ["STRINGS.SKILLTREE.WOODIE.WOODIE_HUMAN_LUCY_2_DESC"] = "ใช้ลูซี่แกะสลักหมวกไม้เนื้อแข็ง(Hardwood Hat)เพื่อป้องกันตัว",
   ["STRINGS.SKILLTREE.WURT.WURT_CIV_1_DESC"] = "เรียนรู้วิธีประดิษฐ์จานสาหร่ายทะเลส่วนกลางเพื่อกระตุ้นให้เมิร์มเติบโตเร็วขึ้น และเรียกเมิร์มมาดำเนินการ",
   ["STRINGS.SKILLTREE.WINONA.WINONA_LUNAR_3_DESC"] = "ใช้ รีโมทที่มีประโยชน์(Handy Remote) ของคุณเพื่อเลือกเป้าหมายสำหรับการโจมตีด้วย Catapult ที่ใช้สาระสำคัญจากดวงจันทร์",
   ["STRINGS.SKILLTREE.WINONA.WINONA_SHADOW_3_DESC"] = "ใช้ รีโมทที่มีประโยชน์(Handy Remote) ของคุณเพื่อเลือกเป้าหมายสำหรับการโจมตีด้วย Catapult ที่ใช้เงา",
   ["STRINGS.SKILLTREE.WURT.WURT_CIV_3_DESC"] = "เรียนรู้การประดิษฐ์อาวุธเพื่อติดตั้ง หมวกนักสู้แห่งหนองบึง สำหรับ เมิร์ม(Merm)การ์ดผู้ภักดี ของคุณ",
   ["STRINGS.SKILLTREE.WALTER.WALTER_WOBY_ENDURANCE_DESC"] = "โวบี้(Woby) ได้รับความเร็วเพิ่มขึ้น 1 ระดับเมื่อวิ่งหรือวิ่งเร็ว และค่าความหิวทั้งหมดลดลง 20%",
   ["STRINGS.SKILLTREE.WURT.WURT_CIV_3_2_DESC"] = "เรียนรู้การประดิษฐ์อาวุธระดับสูง ซึ่งจะให้หมวกนักรบแห่งหนองบึง",
   ["STRINGS.SKILLTREE.WILSON.WILSON_ALCHEMY_10_DESC"] = "แปรรูป อาหารเน่า(Rot) 6 ชิ้น เป็นปุ๋ยคอก(Manure)\nแปรรูป ฟันหมาล่าเนื้อ(Hound) 2 ชิ้น เป็นเศษกระดูก(Bone Shards)\nแปรรูป เศษกระดูก(Bone Shards) 2 ชิ้น เป็นฟันหมาล่าเนื้อ(Hound)",
   ["STRINGS.SKILLTREE.WURT.WURT_MERM_KING_HUNGER_2_DESC"] = "เพิ่มความหิวสูงสุดของ เมิร์ม(Merm) King ให้มากยิ่งขึ้น",
   ["STRINGS.SKILLTREE.WURT.WURT_PATHFINDER_DESC"] = "ผู้รอดชีวิตใกล้ เวิร์ท(Wurt) จะเคลื่อนไหวเช่นเดียวกับเธอผ่านหนองบึง",
   ["STRINGS.SKILLTREE.WURT.WURT_MERMKINGCROWN_DESC"] = "มอบมงกุฎที่กษัตริย์ในอดีตกาลเคยสวมให้แก่เขา และนางมารของคุณก็จะต่อสู้อย่างฉลาดขึ้น เพื่อชีวิตของพวกเขาจะได้ยืนยาว",
   ["STRINGS.SKILLTREE.WALTER.WALTER_WOBY_FORAGING_DESC"] = "โวบี้(Woby) จะออกไปหาอาหารร่วมกับคุณ โดยเก็บอาหารพิเศษหนึ่งรายการจากพืชชนิดเดียวกันที่คุณกำลังเก็บเกี่ยว",
   ["STRINGS.SKILLTREE.WURT.WURT_CIV_1_2_DESC"] = "เรียนรู้วิธีประดิษฐ์จานสาหร่ายทะเลส่วนกลางชั้นยอด ซึ่งจะบรรจุสาหร่ายทะเลได้มากขึ้น ทำให้เมิร์มเติบโตได้เร็วยิ่งขึ้น และเรียกเมิร์มออกมาเพื่อดำเนินการ",
   ["STRINGS.SKILLTREE.WALTER.WALTER_AMMO_LUCKY_DESC"] = "เรียนรู้วิธีสร้าง กระสุนระเบิด(Kablooies) และ กระสุนก้อนกรวด(Dread กระสุนหิน(Pebbles)) กระสุนประเภทนี้ต้องอาศัยโชคในการยิงจึงจะสร้างความเสียหายได้มากขึ้นหรือไม่ก็แตก",
   ["STRINGS.SKILLTREE.WALTER.WALTER_WOBY_SHADOW_TITLE"] = "โวบี้(Woby)เงา(Shadow)",
   ["STRINGS.SKILLTREE.WALTER.WALTER_CAMP_FIRE_TITLE"] = "ผู้ชื่นชอบกองไฟ",
   ["STRINGS.SKILLTREE.WALTER.WALTER_CAMP_WOBYCOURIER_TITLE"] = "ว้าวที่นี่ ว้าวที่นั่น",
   ["STRINGS.SKIN_DESCRIPTIONS.profileflair_knight"] = "ตั้งค่าไอคอนโปรไฟล์ของคุณเป็นอัศวินเครื่องจักร\n\nแม็กซ์เวลล์(Maxwell) ได้ผลิต Clockwork Knights จำนวนมากในรัชสมัยของพระองค์บน บังลังก์ฝันร้าย(Nightmare Throne)",
   ["STRINGS.SKIN_DESCRIPTIONS.pack_pirate_all"] = "หีบ(Chest) Swashbuckler นี้มีสกินสำหรับ: วิกฟริด(Wigfrid), วิลโลว์(Willow), วิโนน่า(Winona), วอทอกซ์?(Wortox)?, วอร์ลี่(Warly), เวส(Wes), วูล์ฟกัง(Wolfgang), วู้ดดี้(Woodie)และ เวิร์ท(Wurt)",
   ["STRINGS.SKIN_DESCRIPTIONS.pack_starter_2024"] = "หีบ(Chest)นี้บรรจุตัวละครที่สามารถเล่นได้, เวิร์ท(Wurt): The Half-Pint, ชุดสกิน Verdant ของ วิลสัน(Wilson), ชุดสกิน Swashbuckler ของ วิลโลว์(Willow), ชุดสกิน Gladiator ของ วูล์ฟกัง(Wolfgang), ชุดสกิน Moonbound ของ WX-78, หน้าอก Pastoral, Narwalrus หีบ(Chest)กระโดด และ Yawny Jammies วงดนตรี",
   ["STRINGS.SKIN_DESCRIPTIONS.walrushat_blue"] = "แลกเปลี่ยน หมวกวอลรัส(Tam o' Shanter) ที่มอดตัวเก่าของคุณไปแลกเป็น หมวกวอลรัส(Tam o' Shanter) ที่กินมอดตัวใหม่!",
   ["STRINGS.SKIN_DESCRIPTIONS.pack_wendy_survivor"] = "หีบ(Chest)นี้บรรจุไอเท็มสกินผู้รอดชีวิตครบชุดของเวนดี้(Wendy)",
   ["STRINGS.SKIN_DESCRIPTIONS.pack_lunar_3_western_1"] = "หีบ(Chest) Moonbound Stampeders นี้ประกอบไปด้วยสกินไอเทม Moonbound ของ วู้ดดี้(Woodie), วอทอกซ์?(Wortox)? และ เวิร์ท(Wurt) และสกินไอเทม Stampeder Duds ของ แวนด้า(Wanda), วิกฟริด(Wigfrid) และ เวส(Wes)",
   ["STRINGS.SKIN_DESCRIPTIONS.pack_wx78_deluxe"] = "ตู้เสื้อผ้า(Wardrobe)แบบดีลักซ์นี้ประกอบด้วยไอเท็มสกิน Guest of Honor, Roseate, Survivor, Triumphant และ Fool ครบชุด",
   ["STRINGS.SKIN_DESCRIPTIONS.pack_walter_deluxe"] = "ตู้เสื้อผ้าสุดหรูนี้ประกอบด้วยชุดสกิน Guest of Honor, Survivor และ Boy Detective ครบชุดของ วอลเตอร์(Walter) รวมถึง Deerstalker, Pine Leader Hat และ Cap o' Flage",
   ["STRINGS.SKIN_DESCRIPTIONS.axe_invisible"] = "ถ่ายทอดความประทับใจอันน่าเชื่ออย่างเหลือเชื่อของขวาน(axe)",
   ["STRINGS.SKIN_DESCRIPTIONS.pack_rose_all"] = "หีบ(Chest) Roseate ชุดนี้ประกอบไปด้วยสกินผู้รอดชีวิตจากซีรีส์ Roseate ครบชุด",
   ["STRINGS.SKIN_DESCRIPTIONS.pack_victorian_wilson"] = "Victorian หีบ(Chest) นี้บรรจุไอเท็มสกิน Victorian ครบชุด",
   ["STRINGS.SKIN_DESCRIPTIONS.pack_wrestler_promo1"] = "กล่องโปรโมชันนี้ประกอบด้วยสกิน Contenders สำหรับ วิกฟริด(Wigfrid), เวส(Wes) และ วูล์ฟกัง(Wolfgang), Golden Helm, Ultimate หอก(Spear), Lover's ร่ม(Umbrella), Lover's ตู้เสื้อผ้า(Wardrobe), Cowboy หมวกฟาง(Straw Hat) และ Prybar ค้อน(Hammer)",
   ["STRINGS.SKIN_DESCRIPTIONS.winona_shadowp"] = "ไม่มีใครรู้ว่าความลึกของเครื่องรางที่มืดของวิโนน่า(Winona)",
   ["STRINGS.SKIN_DESCRIPTIONS.warly_nature"] = "วอร์ลี่(Warly) ได้พบความซาบซึ้งอย่างสุดซึ้งต่อโลกธรรมชาติและทุกสิ่งที่มีให้",
