   ["STRINGS.SKIN_DESCRIPTIONS.pack_wolfgang_strongman"] = "หีบ(Chest)นี้บรรจุไอเท็มสกิน Strongman ครบชุดของ วูล์ฟกัง(Wolfgang)",
